INSERT OR REPLACE INTO clunk_marketplace_listings (id, workspace_id, asset_id, slug, title, description, price_cents, currency, license_status, status, published_at) VALUES ('listing-w1-grove-tree-pack-vol1', 'ws-artemis-store', 'asset-w1-grove-tree-pack-vol1', 'grove-tree-pack-vol1', '그로브 트리 팩 Vol.1 (6 템플릿)', '잎 넓은 나무 4종과 침엽수 2종, 모두 여섯 그루의 가벼운 3D 나무 묶음입니다. 한 그루에 폴리곤 860~2,136개이며, 그루마다 재질 2개·그리기 2회·텍스처 0장으로 통일돼 있습니다. 여섯 그루 모두 웹·모바일 게임 기준 100점, 막히는 문제 0건이고 색이 모델에 들어 있어 텍스처 파일이 없습니다. 멀리서 볼 때 바꿔 끼울 단순 버전(LOD)은 아직 없고, 부품은 줄기와 잎 두 덩이입니다. 뿌리 부분이 바닥보다 최대 0.44 m 아래로 내려가니 땅에 놓을 때 그만큼 올리세요.', 290000, 'KRW', 'cleared', 'PUBLISHED', CURRENT_TIMESTAMP);
