INSERT OR REPLACE INTO clunk_marketplace_listings (id, workspace_id, asset_id, slug, title, description, price_cents, currency, license_status, status, published_at) VALUES ('listing-w1-verified-seamless-textures-vol1', 'ws-artemis-store', 'asset-w1-verified-seamless-textures-vol1', 'verified-seamless-textures-vol1', '이어붙는 텍스처 7종 묶음', '1024×1024 이음매 없는 텍스처 7종을 한 번에 받는 묶음입니다. 이어 붙였을 때 경계가 안 보이는 것이 5종, 경계가 약하게 보이는 것이 2종입니다. 일곱 장이 게임에서 차지하는 그래픽 메모리는 합쳐서 37.33MB로, 흔히 잡는 40MB 예산의 93.3%이고, 장마다 5·15·30 m 거리에서 무늬가 얼마나 살아 있는지 잰 표가 붙습니다. 각 장에 만든 기록(프롬프트·모델·파일 지문)과 검사 보고서가 들어 있습니다. 이음매와 멀리서의 가독성을 말이 아니라 잰 값으로 보여 주는 것이 이 묶음의 차이입니다.', 190000, 'KRW', 'cleared', 'PUBLISHED', CURRENT_TIMESTAMP);
